mapper.select:
SELECT ANUM, AWRITER, ACONTENT,ADATE, row_num FROM (SELECT a.ANUM, a.AWRITER, a.ACONTENT, a.ADATE, ROW_NUMBER() OVER(ORDER BY a.ANUM DESC) AS row_num FROM QNA_A a INNER JOIN MEMBER m ON a.MEMBER_NUM = m.NUM
AND a.awriter LIKE '%' || #{searchValue} || '%' AND a.acontent LIKE '%' || #{searchValue} || '%' AND a.acontent LIKE '%' || #{searchValue} || '%'
) numbered_rows WHERE row_num BETWEEN #{begin} AND #{end}
